// [3. 최종 병합 (Merge)]
// 1차 수집 원본 데이터(original_items)와 2차 AI 분석 결과(aiResults)를 voc_id 기준으로 1:1 결합합니다.
const originalItems = $('Loop Over VOC Batches').first().json.original_items || [];
const rawAiText = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '[]';

let aiResults = [];
try {
  aiResults = JSON.parse(rawAiText.replace(/```json|```/g, '').trim());
} catch (e) {
  aiResults = [];
}

// 빠른 매칭을 위해 voc_id를 Key로 하는 Map 생성
const aiMap = {};
for (const ai of aiResults) {
  if (ai && ai.voc_id) {
    aiMap[ai.voc_id] = ai;
  }
}

// 기존 스키마를 훼손하지 않고 뒤쪽에 AI 분석 칼럼만 이어 붙여서 반환
return originalItems.map(orig => {
  const ai = aiMap[orig.voc_id] || {};
  return {
    json: {
      voc_id: orig.voc_id,
      source_site: orig.source_site || 'Unknown',
      category: orig.category || 'Community/Forum',
      content_type: orig.content_type || 'POST',
      content: orig.content || '',
      parent_id: orig.parent_id || null,
      kr_summary: ai.kr_summary || '(AI 요약 실패 또는 내용 없음)',
      ai_sentiment: ai.ai_sentiment || 'NEUTRAL',
      user_intent: ai.user_intent || 'EXPERIENCE',
      topic_tags: Array.isArray(ai.topic_tags) ? ai.topic_tags : [],
      competitors: Array.isArray(ai.competitors) ? ai.competitors : [],
      is_urgent: Boolean(ai.is_urgent),
      ai_metadata: {
        lg_mentioned: Boolean(ai.lg_mentioned),
        analyzed_at: new Date().toISOString()
      }
    }
  };
});
